class Solution {
public:
    int prev = -1e8;
    int ans = INT_MAX;
    void dfs(TreeNode* root){
        if(root->left) dfs(root->left);
        ans = min(ans,abs(root->val - prev));
        prev = root->val;
        if(root->right) dfs(root->right);
    }
    int getMinimumDifference(TreeNode* root) {
        dfs(root);
        return ans;
    }
};
